-- =====================================================================
-- 0082 — Internal Audit (a new KMR App, for any company: each company sees only its own data)
--  • Audit programme: system, process (VDA 6.3 scoring), product and supplier audits, planned by date, area, auditor and shift.
--  • An audit report with a checklist, a rating per question, findings, and actions with owner, due date and effectiveness check.
--  • Rules in plain words: the auditor must not audit their own work, every question is rated, every finding has an action
--    with an owner and a due date before the report is issued, and an audit is closed only when its actions are checked.
--  • Numbered audits (AUD/26-27/0001), activity log, dashboard (programme completion, shifts covered, late actions), printed audit plan and report.
--  • Sample data to validate the flow and delete again.
-- Needs 0081. Safe to re-run. Generated by scripts/make-aud.py.
-- =====================================================================
do $$ begin
  if to_regprocedure('console.d8_sample(uuid, text)') is null then raise exception 'Run 0080_d8_problem_solving.sql and 0081_qms_learning.sql first.'; end if;
end $$;
insert into console.products (code, name, description, app_path, seat_label, current_version, sort_order) values
  ('aud', 'Internal Audit', 'Audit programme and reports for system, process (VDA 6.3), product and supplier audits, with findings, actions and a printed audit report', '/it/aud.html', 'users', '1.0.0', 17)
on conflict (code) do nothing;
insert into console.releases (product_code, version, notes) values
  ('aud', '1.0.0', 'Internal Audit: programme, checklists, ratings, findings, actions, VDA 6.3 scoring, dashboard, printed plan and report') on conflict do nothing;
insert into console.prices (product_code, period, currency, unit_amount, min_seats, active, note)
select v.code, v.period, 'INR', v.amt, 3, true, 'Starting price list (0082) — per user, change in Console › Billing'
  from (values ('aud', 'month', 70), ('aud', 'year', 700)) v(code, period, amt)
 where not exists (select 1 from console.prices x where x.product_code = v.code and x.currency = 'INR' and x.period = v.period)
on conflict (product_code, period, currency) do nothing;
insert into public.app_listings (code, name, tagline, features, sort_order, is_active) values
  ('aud', 'Internal Audit', 'Plan the year of audits, record what was found and make sure every finding is fixed.',
   E'Audit programme by type, area, auditor and shift, with completion shown on a dashboard\nChecklists with ratings, findings and actions with owners and due dates\nVDA 6.3 scoring, printed audit plan and audit report', 17, true)
on conflict (code) do update set name = excluded.name, tagline = excluded.tagline, features = excluded.features, is_active = true;
insert into console.app_features (product_code, name, detail, is_core, price_month, price_year, setup_fee, sort_order) values
  ('aud', 'Audit programme and reports', 'Yearly programme, audit reports with checklist and ratings, findings, actions, activity log, dashboard and printed forms', true, 20, 0, 5000, 10),
  ('aud', 'Findings tracker', 'All actions of all audits in one list by owner and due date, with effectiveness checks', false, 10, 0, 2500, 20),
  ('aud', 'VDA 6.3 scoring', 'Score and grade (A, B, C) of process audits from the ratings of the questions', false, 10, 0, 2500, 30)
on conflict (product_code, name) do nothing;
delete from console.app_features f where f.product_code = 'aud' and f.name = 'Core platform' and not exists (select 1 from console.invoice_lines il where il.feature_id = f.id);
update console.app_features set price_year = price_month * 10 where product_code = 'aud' and price_year = 0;
select console.sync_app_price('aud');

create table if not exists console.aud_counters (
  customer_id uuid not null references console.customers(id) on delete cascade, key text not null, n bigint not null default 0, sample boolean not null default false, primary key (customer_id, key));
create table if not exists console.aud_settings (
  customer_id uuid primary key references console.customers(id) on delete cascade, data jsonb not null default '{}', sample boolean not null default false, updated_at timestamptz not null default now());
create table if not exists console.aud_audits (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  no text not null, title text not null, type text not null default 'System' check (type in ('System', 'Process', 'Product', 'Supplier')),
  status text not null default 'planned' check (status in ('planned', 'reported', 'closed', 'cancelled')),
  area text, scope text, planned_on date, done_on date, auditor text, auditee text, shifts jsonb not null default '[]',
  checklist jsonb not null default '[]', summary text, score numeric(5,1), grade text, reported_on date, closed_on date,
  sample boolean not null default false, created_by text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (customer_id, no));
create index if not exists aud_audits_plan on console.aud_audits (customer_id, status, planned_on);
create table if not exists console.aud_actions (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  audit_id uuid not null references console.aud_audits(id) on delete cascade, q_id text, text text not null, owner text, due_on date,
  status text not null default 'open' check (status in ('open', 'done')), done_on date, evidence text, verified boolean not null default false, verified_on date,
  sample boolean not null default false, created_by text, created_at timestamptz not null default now());
create index if not exists aud_actions_audit on console.aud_actions (audit_id);
create index if not exists aud_actions_open on console.aud_actions (customer_id, status, due_on);
create table if not exists console.aud_log (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  audit_id uuid not null references console.aud_audits(id) on delete cascade, at timestamptz not null default now(), by text, text text not null, sample boolean not null default false);
create index if not exists aud_log_audit on console.aud_log (audit_id, at);
do $$ declare t text; begin foreach t in array array['aud_counters','aud_settings','aud_audits','aud_actions','aud_log'] loop
  execute format('alter table console.%I enable row level security', t);
  execute format('drop policy if exists %I on console.%I', t || '_staff', t);
  execute format('create policy %I on console.%I for all to authenticated using (console.is_staff()) with check (console.is_staff())', t || '_staff', t);
end loop; end $$;

